# Generated by Phase: IMPLEMENT | Feature: EVOL-065
"""Where does this write land — one answer for every tool (EVOL-065).

Edit / Write / MultiEdit give `tool_input.file_path`. Bash gives the targets of the recognised writers in
`tool_input.command`: redirections (> >> >| &> &>> N>), tee, sed -i, cp (destination), mv (sources and
destination), and an inline interpreter program (#227) — python `-c PROG`, node `-e|--eval|-p|--print PROG`, or a
heredoc on stdin (`- <<EOF`, `<<EOF` with no script). Python is read by its AST, node by a light scanner; a target is
a literal, a name bound exactly once (module scope) to one, a path built over literals (Path(…), `/`, path.join),
`sys.argv[N]`, joined to a literal working directory set once before it. Python writers: open / io.open / X.open
with a write mode, os.open with a write flag, write_text|write_bytes, os.replace|rename, shutil copy / move
destinations, a path's replace|rename(target). Node: writeFile, appendFile, createWriteStream (first argument),
copyFile, rename, cp (second), open with a write flag — Sync or not. A recognised writer whose target is computed is
unresolved, never guessed. Anything else is not a writer (bash -c, a script file, a program piped in, xargs /
find -exec, build scripts, git apply — pre-commit stays their backstop). A wrapper or a reserved word before the
command (sudo, env, do, then, {, !) never hides it.

Verdict, in order: guarded (harness / user configuration, the git dir) → 1 · unresolved → 1 (route: Edit or Write)
· every target outside the project → 4 (nothing to judge; 3 is gate.py's import guard) · in-project targets → 0, one per line.
Deploy class (EVOL-081), judged after guarded: the command's words after the wrappers (bash -c read through) start
with the adapter's own apply / destroy (config/quality.json → delivery.adapter, up to the first flag) and
delivery.execution is ci → 5. Unreadable config or a null adapter → no class (fail open).
"""
from __future__ import annotations

import ast
import json
import os
import re
import shlex
import subprocess
from pathlib import Path

# leading words that run the next word as the command: wrappers, and the reserved words a loop or a conditional opens with
PREFIX_WORDS = {"env", "command", "exec", "nohup", "time", "sudo", "if", "then", "elif", "else", "do", "while", "until", "{", "!"}
SEPARATORS = {";", "&&", "||", "|", "|&", "&", "(", ")", "\n", ";;"}
SPECIAL = "#;&|()<>\n"   # quoted or escaped, these are word characters: masked before shlex, restored in the word
MASK = {c: chr(0xE000 + i) for i, c in enumerate(SPECIAL)}
UNMASK = str.maketrans({v: k for k, v in MASK.items()})
BRACE = re.compile(r"\{[^{}]*(,|\.\.)[^{}]*\}")
FILE_REDIR = {">", ">>", ">|", "&>", "&>>", "<>"}
OPS = re.compile(r"&>>|&>|>>|>\||>&|<<<|<<|<&|<>|&&|\|\||\|&|;;|[;&|()<>\n]")
HEREDOC = re.compile(r"(?<!<)<<(-?)(?!<)[ \t]*(['\"]?)([A-Za-z_][A-Za-z0-9_]*)\2")
VAR = re.compile(r"\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))")
ASSIGN = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)=(.*)$", re.S)
ENV_FALLBACK = ("HOME", "CLAUDE_PROJECT_DIR", "TMPDIR")
EDIT_TOOLS = {"Edit", "Write", "MultiEdit"}
HDOC_MARK = chr(0xE100)   # a private-use character: the placeholder word of a heredoc body (#227)
HDOC_WORD = re.compile(HDOC_MARK + r"(\d+)")
PATH_CTORS = {"Path", "pathlib.Path", "PurePath", "pathlib.PurePath", "PosixPath", "pathlib.PosixPath"}
OS_WRITE_FLAGS = {"O_WRONLY", "O_RDWR", "O_CREAT", "O_APPEND", "O_TRUNC"}
SHUTIL_DEST = {"shutil.copy", "shutil.copy2", "shutil.copyfile", "shutil.move", "shutil.copytree"}
JS_FIRST = {"writeFile", "writeFileSync", "appendFile", "appendFileSync", "createWriteStream"}
JS_SECOND = {"copyFile", "copyFileSync", "rename", "renameSync", "cp", "cpSync"}
JS_OPEN = {"open", "openSync"}
JS_BARE = {"writeFile", "writeFileSync", "appendFile", "appendFileSync", "createWriteStream", "copyFileSync", "renameSync", "cpSync"}
JS_ID = re.compile(r"[A-Za-z_$][\w$]*")
JS_OP = re.compile(r"===|!==|==|!=|<=|>=|=>|\+\+|--|\?\?=|\|\|=|&&=|[-+*/%]=|\.\.\.")
JS_ASSIGN = {"=", "+=", "-=", "*=", "/=", "%=", "??=", "||=", "&&=", "++", "--"}


class Unresolved(Exception):
    """A recognised writer whose target cannot be named before it runs."""


def _drop_heredocs(text: str) -> tuple[str, list[str]]:
    """The command without its heredoc bodies, each `<<[-]WORD` replaced by a placeholder word that names its body —
    the body is the command's stdin (an interpreter's program), never a word of the command line."""
    out, pending, bodies = [], [], []
    for line in text.split("\n"):
        if pending:
            strip_tabs, word, k = pending[0]
            line = line.lstrip("\t") if strip_tabs else line
            if line == word:
                pending.pop(0)
            else:
                bodies[k].append(line)
            continue
        def sub(m):
            pending.append((m.group(1) == "-", m.group(3), len(bodies)))
            bodies.append([])
            return f" {HDOC_MARK}{len(bodies) - 1} "
        out.append(HEREDOC.sub(sub, line))
    return "\n".join(out), ["\n".join(b) for b in bodies]


def _mask(text: str) -> str:
    """The quoting shlex drops, kept: a quoted or escaped special character is masked (a word character); an unquoted
    `#` at a word start drops the rest of the line (a comment); a backslash-newline joins the lines."""
    out, q, i, n = [], None, 0, len(text)
    while i < n:
        c = text[i]
        if c == "\\" and q != "'" and i + 1 < n:
            nxt = text[i + 1]
            if nxt == "\n":
                i += 2; continue
            if nxt in MASK:   # outside quotes the escape makes it a word character; inside "…" the backslash stays literal
                out.append(MASK[nxt] if q is None else c + MASK[nxt])
            else:
                out.append(c + nxt)
            i += 2; continue
        if q is None:
            if c in "'\"":
                q = c
            elif c == "#" and (not out or out[-1] in " \t\r;&|()<>\n"):   # an escaped pair (`\ #`) is a word, never its start
                j = text.find("\n", i)
                i = n if j < 0 else j
                continue
        elif c == q:
            q = None
        elif c in MASK:
            c = MASK[c]
        out.append(c)
        i += 1
    return "".join(out)


def _lex(text: str) -> list[str]:
    lx = shlex.shlex(_mask(text), posix=True, punctuation_chars=";&|()<>\n")
    lx.whitespace = " \t\r"
    lx.whitespace_split = True
    lx.commenters = ""
    words = []
    for tok in lx:
        if tok and all(c in ";&|()<>\n" for c in tok):
            words.extend(("op", o) for o in OPS.findall(tok))
        else:
            words.append(("w", tok.translate(UNMASK)))
    return words


def _commands(words) -> list:
    """Simple commands, with "(" and ")" kept as markers: a subshell's cd stays in the subshell."""
    cmds, cur = [], []
    for kind, tok in words:
        if kind == "op" and tok in SEPARATORS:
            if cur:
                cmds.append(cur)
            cur = []
            if tok in "()":
                cmds.append(tok)
            continue
        cur.append((kind, tok))
    if cur:
        cmds.append(cur)
    return cmds


class _Reader:
    def __init__(self, repo: Path, cwd: str | None, env: dict):
        self.repo, self.env = repo, env
        self.cwd: str | None = os.path.realpath(cwd) if cwd else str(repo)
        self.vars: dict[str, str | None] = {}
        self.targets: list[str] = []
        self.unresolved: str | None = None
        self.writer = False
        self.argvs: list[list[str]] = []   # each simple command's words after the wrappers (the deploy class reads them)
        self.bodies: list[str] = []        # the heredoc bodies, by placeholder index

    # ── words → paths ──
    def expand(self, word: str) -> str:
        if "`" in word or "$(" in word:
            raise Unresolved(f"a command substitution in «{word}»")
        if word == "~" or word.startswith("~/"):
            home = self.env.get("HOME")
            if not home:
                raise Unresolved(f"«{word}» names a home directory that is not set")
            word = home + word[1:]

        def sub(m):
            name = m.group(1) or m.group(2)
            val = self.vars.get(name) if name in self.vars else (self.env.get(name) if name in ENV_FALLBACK else None)
            if val is None:
                raise Unresolved(f"the variable ${name} is not set in the command")
            return val
        word = VAR.sub(sub, word)
        if "$" in word:
            raise Unresolved(f"a shell expansion in «{word}»")
        if any(c in word for c in "*?["):
            raise Unresolved(f"a glob in «{word}»")
        if BRACE.search(word):
            raise Unresolved(f"a brace expansion in «{word}»")
        return word

    def path(self, word: str) -> str:
        p = self.expand(word)
        if not os.path.isabs(p):
            if self.cwd is None:
                raise Unresolved(f"«{word}» is relative to a directory the command changed to through an expansion")
            p = os.path.join(self.cwd, p)
        return os.path.realpath(p)

    def hit(self, word: str):
        self.writer = True
        self.targets.append(self.path(word))

    def lit_path(self, p: str, base) -> str:
        """A path an interpreter program names: never shell-expanded; relative to `base` (False: a working directory
        the program changed to through a value the guard cannot name)."""
        if not os.path.isabs(p):
            if base is False:
                raise Unresolved(f"«{p}» is relative to a working directory the program changes through a value the guard cannot name")
            if base is None:
                raise Unresolved(f"«{p}» is relative to a directory the command changed to through an expansion")
            p = os.path.join(base, p)
        return os.path.realpath(p)

    def hit_path(self, path: str):
        self.writer = True
        self.targets.append(path)

    # ── one simple command ──
    def run(self, cmd):
        args, redirs, i, stdin = [], [], 0, None
        while i < len(cmd):
            kind, tok = cmd[i]
            if kind == "w" and HDOC_WORD.fullmatch(tok):
                k = int(HDOC_WORD.fullmatch(tok).group(1))
                stdin = self.bodies[k] if k < len(self.bodies) else None
                i += 1
                continue
            if kind == "op":
                nxt = cmd[i + 1][1] if i + 1 < len(cmd) and cmd[i + 1][0] == "w" else None
                if args and re.fullmatch(r"\d+", args[-1]) and tok in FILE_REDIR | {">&", "<", "<&"}:
                    args.pop()   # an all-digit word right before a redirection is its fd
                if tok in FILE_REDIR and nxt is not None:
                    redirs.append(nxt)
                elif tok == ">&" and nxt is not None and not re.fullmatch(r"\d+|-", nxt):
                    redirs.append(nxt)
                i += 2 if nxt is not None else 1
                continue
            args.append(tok)
            i += 1
        for r in redirs:
            self.hit(r)
        while args and ASSIGN.match(args[0]):
            name, val = ASSIGN.match(args.pop(0)).groups()
            try:
                self.vars[name] = self.expand(val) if val else ""
            except Unresolved:
                self.vars[name] = None
        while args and args[0] in PREFIX_WORDS | {"export"}:
            pre = args.pop(0)
            while args and (args[0].startswith("-") or ASSIGN.match(args[0])):
                flag = args.pop(0)
                m = ASSIGN.match(flag)
                if not m and flag in VALUED.get(pre, ()) and args:
                    args.pop(0)   # `sudo -u root …`, `env -u X …`: the option's value is never the command
                if m:
                    try:
                        self.vars[m.group(1)] = self.expand(m.group(2))
                    except Unresolved:
                        self.vars[m.group(1)] = None
        if not args:
            return
        name, rest = os.path.basename(args[0]), args[1:]
        self.argvs.append([name, *rest])
        if name == "cd":
            self._cd(rest)
        elif name == "tee":
            for a in _operands(rest):
                self.hit(a)
        elif name == "sed":
            self._sed(rest)
        elif name in ("cp", "mv"):
            self._copy(name, rest)
        elif re.fullmatch(r"python(\d+(\.\d+)?)?", name):
            self._python(rest, stdin)
        elif name in ("node", "nodejs"):
            self._node(rest, stdin)

    def _cd(self, rest):
        dest = rest[0] if rest else "~"
        try:
            self.cwd = self.path(dest) if dest != "-" else None
        except Unresolved:
            self.cwd = None

    def _sed(self, rest):
        inplace, script_given, operands, i = False, False, [], 0
        while i < len(rest):
            a = rest[i]
            if a == "--":
                operands.extend(rest[i + 1:]); break
            if a.startswith("--"):
                if a == "--in-place" or a.startswith("--in-place="):
                    inplace = True
                elif a in ("--expression", "--file", "--line-length"):
                    script_given = script_given or a != "--line-length"; i += 1
                elif a.startswith(("--expression=", "--file=")):
                    script_given = True
            elif a.startswith("-") and len(a) > 1:
                for j, c in enumerate(a[1:], 1):
                    if c == "i":
                        inplace = True; break
                    if c in "efl":
                        script_given = script_given or c != "l"
                        if j == len(a) - 1:
                            i += 1
                        break
            else:
                operands.append(a)
            i += 1
        if not inplace:
            return
        for a in operands[0 if script_given else 1:]:
            self.hit(a)

    def _copy(self, name, rest):
        target_dir, operands, i = None, [], 0
        while i < len(rest):
            a = rest[i]
            if a == "--":
                operands.extend(rest[i + 1:]); break
            if a in ("-t", "--target-directory"):
                target_dir = rest[i + 1] if i + 1 < len(rest) else None; i += 2; continue
            if a.startswith("--target-directory="):
                target_dir = a.split("=", 1)[1]
            elif a.startswith("-t") and len(a) > 2:
                target_dir = a[2:]
            elif a.startswith("-") and len(a) > 1:
                pass
            else:
                operands.append(a)
            i += 1
        brace = next((o for o in operands if BRACE.search(o)), None)
        if brace is not None:
            raise Unresolved(f"a brace expansion in «{brace}»")   # `cp f{,.bak}` is two operands the reader does not expand
        if target_dir is not None:
            dest, sources, into = target_dir, operands, True
        else:
            if len(operands) < 2:
                return
            dest, sources = operands[-1], operands[:-1]
            into = len(sources) > 1 or os.path.isdir(self.path(dest))
        d = self.path(dest)
        self.writer = True
        for s in sources:
            if name == "mv":
                self.hit(s)
            if not into:
                self.targets.append(d)
                continue
            try:
                self.targets.append(os.path.join(d, os.path.basename(self.expand(s).rstrip("/"))))
            except Unresolved:   # mv's sources are hit above: only cp reaches here
                self.targets.append(os.path.join(d, "*"))   # a source the reader cannot name, into a named directory: its content is judged

    def _python(self, rest, stdin):
        """The program: `-c PROG` (also in a cluster, `-Ic PROG`), or stdin after `-` or after no script."""
        i = 0
        while i < len(rest):
            a = rest[i]
            if a == "-":
                return _PyProgram(self, stdin, rest[i:]).run()
            if a.startswith("--"):
                i += 1; continue
            if not a.startswith("-"):
                return   # a script file: not a recognised writer
            for j, c in enumerate(a[1:], 1):
                if c == "c":
                    if a[j + 1:]:
                        return _PyProgram(self, a[j + 1:], ["-c", *rest[i + 1:]]).run()
                    return _PyProgram(self, rest[i + 1] if i + 1 < len(rest) else None, ["-c", *rest[i + 2:]]).run()
                if c == "m":
                    return   # a module: not a recognised writer
                if c in "WX":
                    i += 0 if a[j + 1:] else 1   # the option's value
                    break
            i += 1
        return _PyProgram(self, stdin, [""]).run()

    def _node(self, rest, stdin):
        """The program: `-e|--eval|-p|--print PROG` (or `=PROG`), or stdin after `-` or after no script."""
        i = 0
        while i < len(rest):
            a = rest[i]
            if a in ("-e", "--eval", "-p", "--print"):
                return _JsProgram(self, rest[i + 1] if i + 1 < len(rest) else None).run()
            if a.startswith(("--eval=", "--print=")):
                return _JsProgram(self, a.split("=", 1)[1]).run()
            if a == "-":
                return _JsProgram(self, stdin).run()
            if a in ("-r", "--require", "--import", "-C", "--conditions", "--loader", "--experimental-loader"):
                i += 2; continue
            if not a.startswith("-"):
                return   # a script file: not a recognised writer
            i += 1
        return _JsProgram(self, stdin).run()


class _PyProgram:
    """An inline python program read by its AST (#227): the recognised writers and their resolvable targets."""

    def __init__(self, reader: _Reader, code: str | None, argv: list[str]):
        self.r, self.code, self.argv = reader, code, argv

    def run(self):
        if self.code is None:
            return
        try:
            tree = ast.parse(self.code)
        except (SyntaxError, ValueError):
            return   # a program that cannot run writes nothing
        stores: dict[str, int] = {}
        self.modules: set[str] = set()
        for n in ast.walk(tree):
            names = []
            if isinstance(n, ast.Name) and isinstance(n.ctx, (ast.Store, ast.Del)):
                names = [n.id]
            elif isinstance(n, ast.arg):
                names = [n.arg]
            elif isinstance(n, ast.alias):
                names = [(n.asname or n.name).split(".")[0]]
                self.modules.add(names[0])
            elif isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                names = [n.name]
            elif isinstance(n, ast.ExceptHandler) and n.name:
                names = [n.name]
            elif isinstance(n, (ast.Global, ast.Nonlocal)):
                names = list(n.names)
            for x in names:
                stores[x] = stores.get(x, 0) + 1
        self.bound: dict[str, ast.AST] = {}
        for st in tree.body:   # a name bound exactly once, at module scope, by a plain assignment
            if isinstance(st, ast.Assign) and len(st.targets) == 1 and isinstance(st.targets[0], ast.Name):
                name, value = st.targets[0].id, st.value
            elif isinstance(st, ast.AnnAssign) and isinstance(st.target, ast.Name) and st.value is not None:
                name, value = st.target.id, st.value
            else:
                continue
            if stores.get(name) == 1:
                self.bound[name] = value
        self.chdir = None   # None: the shell's cwd · (line, dir): a literal chdir · False: a chdir the guard cannot name
        calls = [n for n in ast.walk(tree) if isinstance(n, ast.Call) and _dotted(n.func) in ("os.chdir", "chdir")]
        if calls:
            c = calls[0]
            top = any(isinstance(st, ast.Expr) and st.value is c for st in tree.body)
            d = self.resolve(c.args[0]) if len(calls) == 1 and top and len(c.args) == 1 else None
            try:
                self.chdir = (c.lineno, self.r.lit_path(d, self.r.cwd)) if d is not None else False
            except Unresolved:
                self.chdir = False
        for n in ast.walk(tree):
            if isinstance(n, ast.Call):
                self.call(n)

    def resolve(self, n, depth: int = 0) -> str | None:
        """The path an expression names, or None when it is computed."""
        if depth > 20:
            return None
        if isinstance(n, ast.Constant) and isinstance(n.value, str):
            return n.value
        if isinstance(n, ast.JoinedStr):
            return "".join(v.value for v in n.values) if all(isinstance(v, ast.Constant) for v in n.values) else None
        if isinstance(n, ast.Name):
            return self.resolve(self.bound[n.id], depth + 1) if n.id in self.bound else None
        if isinstance(n, ast.Subscript) and _dotted(n.value) == "sys.argv":
            k = n.slice.value if isinstance(n.slice, ast.Constant) and type(n.slice.value) is int else None
            if k is None or not 0 < k < len(self.argv):
                return None
            try:
                return self.r.expand(self.argv[k])   # the shell expanded the word before python saw it
            except Unresolved:
                return None
        if isinstance(n, ast.BinOp) and isinstance(n.op, ast.Div):
            a, b = self.resolve(n.left, depth + 1), self.resolve(n.right, depth + 1)
            return os.path.join(a, b) if a is not None and b is not None else None
        if isinstance(n, ast.Call):
            if _dotted(n.func) in PATH_CTORS and not n.keywords:
                parts = [self.resolve(a, depth + 1) for a in n.args]
                return None if None in parts else (os.path.join(*parts) if parts else ".")
            if isinstance(n.func, ast.Attribute) and n.func.attr in ("resolve", "absolute") and not n.args:
                return self.resolve(n.func.value, depth + 1)
        return None

    def path(self, n) -> str:
        p = self.resolve(n)
        if p is None:
            raise Unresolved(f"a python write whose target is computed in the program (line {getattr(n, 'lineno', '?')})")
        base = self.r.cwd
        if self.chdir is False:
            base = False
        elif self.chdir is not None and getattr(n, "lineno", 0) > self.chdir[0]:
            base = self.chdir[1]
        return self.r.lit_path(p, base)

    def call(self, n):
        f, name = n.func, _dotted(n.func)
        attr = f.attr if isinstance(f, ast.Attribute) else None
        arg = lambda k, kw: n.args[k] if len(n.args) > k else next((x.value for x in n.keywords if x.arg in kw), None)   # noqa: E731
        if name == "os.open":
            flags = arg(1, ("flags",))
            if flags is not None and {x.attr if isinstance(x, ast.Attribute) else x.id for x in ast.walk(flags) if isinstance(x, (ast.Attribute, ast.Name))} & OS_WRITE_FLAGS:
                self.r.hit_path(self.path(arg(0, ("path",))))
        elif name in ("os.replace", "os.rename"):
            dst = arg(1, ("dst",))
            if dst is not None:
                self.r.hit_path(self.path(dst))
        elif name in SHUTIL_DEST:
            src, dst = arg(0, ("src",)), arg(1, ("dst",))
            if dst is None:
                return
            d = self.path(dst)
            if name == "shutil.copytree":
                self.r.hit_path(os.path.join(d, "*"))
            elif name != "shutil.copyfile" and os.path.isdir(d):
                s = self.resolve(src) if src is not None else None
                self.r.hit_path(os.path.join(d, os.path.basename(s.rstrip("/")) if s else "*"))
            else:
                self.r.hit_path(d)
        elif attr in ("write_text", "write_bytes"):
            self.r.hit_path(self.path(f.value))
        elif attr in ("replace", "rename") and len(n.args) == 1 and not n.keywords:
            self.r.hit_path(self.path(n.args[0]))   # a path's replace / rename: str.replace takes two
        elif name in ("open", "io.open", "codecs.open") or attr == "open":
            module = name in ("open", "io.open", "codecs.open") or (isinstance(f.value, ast.Name) and f.value.id in self.modules)
            mode = arg(1, ("mode",)) if module else arg(0, ("mode",))
            if mode is None:
                return   # the default mode reads
            m = mode.value if isinstance(mode, ast.Constant) and isinstance(mode.value, str) else None
            if m is not None and not set(m) & set("wax+"):
                return
            if m is None:
                raise Unresolved(f"a python open whose mode is computed in the program (line {n.lineno})")
            target = arg(0, ("file", "filename", "name")) if module else f.value
            if target is None:
                raise Unresolved(f"a python open with no target (line {n.lineno})")
            self.r.hit_path(self.path(target))


def _dotted(n) -> str | None:
    if isinstance(n, ast.Name):
        return n.id
    if isinstance(n, ast.Attribute):
        head = _dotted(n.value)
        return f"{head}.{n.attr}" if head else None
    return None


def _js_tokens(code: str) -> list[tuple[str, str | None]]:
    """Strings ("s", value — None when it escapes or interpolates), identifiers ("id"), punctuation ("p"); comments
    and whitespace dropped. A regex literal is not read — a light scanner, never a parser."""
    toks, i, n = [], 0, len(code)
    while i < n:
        c = code[i]
        if c.isspace():
            i += 1; continue
        if code.startswith("//", i):
            j = code.find("\n", i); i = n if j < 0 else j; continue
        if code.startswith("/*", i):
            j = code.find("*/", i + 2); i = n if j < 0 else j + 2; continue
        if c in "'\"`":
            j, buf, plain = i + 1, [], True
            while j < n and code[j] != c:
                if code[j] == "\\":
                    plain = False; j += 2; continue
                if c == "`" and code.startswith("${", j):
                    plain = False
                buf.append(code[j]); j += 1
            toks.append(("s", "".join(buf) if plain else None))
            i = j + 1; continue
        m = JS_ID.match(code, i) or JS_OP.match(code, i)
        if m:
            toks.append(("id" if JS_ID.match(code, i) else "p", m.group())); i = m.end(); continue
        toks.append(("p", c)); i += 1
    return toks


def _js_args(toks, k) -> tuple[list[list], int]:
    """The top-level arguments of the call whose "(" is at k, and the index after its ")"."""
    args, cur, depth, i = [], [], 0, k + 1
    while i < len(toks):
        t = toks[i]
        if t[0] == "p" and t[1] in "([{":
            depth += 1
        elif t[0] == "p" and t[1] in ")]}":
            if depth == 0:
                break
            depth -= 1
        if t == ("p", ",") and depth == 0:
            args.append(cur); cur = []
        else:
            cur.append(t)
        i += 1
    if cur:
        args.append(cur)
    return args, i + 1


class _JsProgram:
    """An inline node program read by a light scanner (#227): the fs writers and their resolvable targets."""

    def __init__(self, reader: _Reader, code: str | None):
        self.r, self.code = reader, code

    def run(self):
        if self.code is None:
            return
        t = self.toks = _js_tokens(self.code)
        assigns: dict[str, int] = {}
        for i, (kind, v) in enumerate(t):
            if kind != "id" or (i and t[i - 1] == ("p", ".")):
                continue
            after = t[i + 1] if i + 1 < len(t) else None
            before = t[i - 1] if i else None
            if (after and after[0] == "p" and after[1] in JS_ASSIGN) or (before and before[0] == "p" and before[1] in ("++", "--")):
                assigns[v] = assigns.get(v, 0) + 1
        self.bound: dict[str, list] = {}
        for i, (kind, v) in enumerate(t):
            if kind == "id" and v in ("const", "let", "var"):
                j = i + 1
                while j + 1 < len(t) and t[j][0] == "id" and t[j + 1] == ("p", "="):
                    name, j, expr, depth = t[j][1], j + 2, [], 0
                    while j < len(t):
                        x = t[j]
                        if x[0] == "p" and x[1] in "([{":
                            depth += 1
                        elif x[0] == "p" and x[1] in ")]}":
                            if depth == 0:
                                break
                            depth -= 1
                        elif depth == 0 and (x in (("p", ","), ("p", ";")) or x in (("id", "const"), ("id", "let"), ("id", "var"))):
                            break
                        expr.append(x); j += 1
                    if assigns.get(name) == 1:
                        self.bound[name] = expr
                    if j < len(t) and t[j] == ("p", ","):
                        j += 1
                    else:
                        break
        self.chdir = None
        sites = [i for i in range(len(t) - 3) if t[i] == ("id", "process") and t[i + 1] == ("p", ".") and t[i + 2] == ("id", "chdir") and t[i + 3] == ("p", "(")]
        if sites:
            args, _ = _js_args(t, sites[0] + 3)
            d = self.resolve(args[0]) if len(sites) == 1 and len(args) == 1 else None
            try:
                self.chdir = (sites[0], self.r.lit_path(d, self.r.cwd)) if d is not None else False
            except Unresolved:
                self.chdir = False
        for i in range(len(t) - 1):
            kind, v = t[i]
            if kind != "id" or t[i + 1] != ("p", "(") or not (v in JS_FIRST or v in JS_SECOND or v in JS_OPEN):
                continue
            method = i > 0 and t[i - 1] == ("p", ".")
            if not method and (v not in JS_BARE or (i and t[i - 1] == ("id", "function"))):
                continue
            args, _ = _js_args(t, i + 1)
            if v in JS_FIRST and args:
                self.r.hit_path(self.path(args[0], i))
            elif v in JS_SECOND and len(args) > 1:
                self.r.hit_path(self.path(args[1], i))
            elif v in JS_OPEN and len(args) > 1:
                m = self.resolve(args[1])
                if m is None:
                    raise Unresolved("a node open whose flags are computed in the program")
                if set(m) & set("wax+"):
                    self.r.hit_path(self.path(args[0], i))

    def resolve(self, expr, depth: int = 0) -> str | None:
        if depth > 20 or not expr:
            return None
        if len(expr) == 1 and expr[0][0] == "s":
            return expr[0][1]
        if len(expr) == 1 and expr[0][0] == "id":
            return self.resolve(self.bound[expr[0][1]], depth + 1) if expr[0][1] in self.bound else None
        if (len(expr) >= 5 and expr[0][0] == "id" and expr[1] == ("p", ".") and expr[2] in (("id", "join"), ("id", "resolve"))
                and expr[3] == ("p", "(") and expr[-1] == ("p", ")") and self._is_path_module(expr[0][1])):
            args, end = _js_args(expr, 3)
            if end != len(expr):
                return None
            parts = [self.resolve(a, depth + 1) for a in args]
            return None if None in parts or not parts else os.path.join(*parts)
        return None

    def _is_path_module(self, name: str) -> bool:
        e = self.bound.get(name)
        return name == "path" or (e is not None and len(e) == 4 and e[0] == ("id", "require") and e[2] in (("s", "path"), ("s", "node:path")))

    def path(self, expr, at: int) -> str:
        p = self.resolve(expr)
        if p is None:
            raise Unresolved("a node write whose target is computed in the program")
        base = self.r.cwd
        if self.chdir is False:
            base = False
        elif self.chdir is not None and at > self.chdir[0]:
            base = self.chdir[1]
        return self.r.lit_path(p, base)


def _operands(rest):
    out, opts = [], True
    for a in rest:
        if opts and a == "--":
            opts = False
        elif opts and a.startswith("-") and len(a) > 1:
            continue
        else:
            out.append(a)
    return out


def _bash(repo: Path, command: str, cwd: str | None, env: dict) -> _Reader:
    r = _Reader(repo, cwd, env)
    try:
        text, r.bodies = _drop_heredocs(command)
        cmds = _commands(_lex(text))
    except ValueError:
        if re.search(r">|\b(tee|sed|cp|mv|python[0-9.]*|node(js)?)\b", command):
            r.writer, r.unresolved = True, "the command could not be read (unbalanced quotes)"
        return r
    stack = []
    for c in cmds:
        if c == "(":
            stack.append(r.cwd); continue
        if c == ")":
            if stack:
                r.cwd = stack.pop()
            continue
        try:
            r.run(c)
        except Unresolved as e:
            r.writer, r.unresolved = True, str(e)
            break
    return r


def _git(repo: Path, *args) -> str:
    try:
        return subprocess.run(["git", "-C", str(repo), *args], capture_output=True, text=True, timeout=10).stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return ""


def guarded_roots(repo: Path, env: dict) -> tuple[set[str], list[str]]:
    """(exact files, directory prefixes) guarded on every branch: the harness and user configuration, the git dir."""
    exact, prefixes = {os.path.realpath(repo / ".claude/settings.local.json")}, []
    home = env.get("HOME")
    if home:
        h = Path(home)
        exact |= {os.path.realpath(h / ".claude/settings.json"), os.path.realpath(h / ".claude/settings.local.json"), os.path.realpath(h / ".gitconfig")}
        prefixes += [os.path.realpath(h / ".claude/hooks"), os.path.realpath(h / ".config/git")]
    for flag in ("--git-common-dir", "--git-dir"):
        g = _git(repo, "rev-parse", flag)
        if g:
            prefixes.append(os.path.realpath(g if os.path.isabs(g) else repo / g))
    hp = _git(repo, "config", "--get", "core.hooksPath")
    if hp:
        if hp.startswith("~/") and home:
            hp = home + hp[1:]
        hp = os.path.realpath(hp if os.path.isabs(hp) else repo / hp)
        if not _within(hp, str(repo)):
            prefixes.append(hp)
    return exact, prefixes


def _within(path: str, root: str) -> bool:
    try:
        return os.path.commonpath([root, path]) == root
    except ValueError:
        return False


def targets(repo: Path, payload: dict, env: dict | None = None) -> dict:
    """Resolve a PreToolUse payload: {tool, writer, inside (repo-relative), guarded, unresolved, pathless}."""
    env = dict(os.environ if env is None else env)
    root = os.path.realpath(repo)
    ti = payload.get("tool_input") or {}
    tool = payload.get("tool_name") or ("Edit" if "file_path" in ti else "Bash" if "command" in ti else "")
    out = {"tool": tool, "writer": False, "inside": [], "guarded": [], "unresolved": None, "pathless": False}
    cwd = payload.get("cwd") or None
    if tool in EDIT_TOOLS:
        out["writer"] = True
        fp = ti.get("file_path") or ""
        if not fp:
            out["pathless"] = True
            return out
        paths = [os.path.realpath(fp if os.path.isabs(fp) else os.path.join(cwd or root, fp))]
    elif tool == "Bash":
        r = _bash(Path(root), str(ti.get("command") or ""), cwd, env)
        out["writer"], out["unresolved"], paths = r.writer, r.unresolved, r.targets
    else:
        return out
    exact, prefixes = guarded_roots(Path(root), env)
    for p in dict.fromkeys(paths):
        if p in exact or any(_within(p, g) for g in prefixes):
            out["guarded"].append(p)
        elif _within(p, root):
            out["inside"].append(os.path.relpath(p, root))
    return out


SHELLS = {"bash", "sh", "zsh", "dash"}


def _shell_script(rest):
    """The script of `bash -c SCRIPT` (also -lc, -ec …), or None."""
    for i, a in enumerate(rest):
        if not a.startswith("-") or a.startswith("--"):
            return None
        if "c" in a[1:]:
            return rest[i + 1] if i + 1 < len(rest) else None
    return None


def _argvs(repo: Path, command: str, cwd: str | None, env: dict, depth: int = 0) -> list[list[str]]:
    """Every simple command's words after the wrappers, `bash -c` read through."""
    out = []
    for args in _bash(repo, command, cwd, env).argvs:
        script = _shell_script(args[1:]) if args[0] in SHELLS and depth < 3 else None
        out += _argvs(repo, script, cwd, env, depth + 1) if script is not None else [args]
    return out


def _deploy_row(repo: Path) -> tuple[str | None, list[list[str]]]:
    """(delivery.execution, the leading words of the adapter's apply / destroy up to the first flag) — EVOL-081.
    Only the LAST simple command of each is the deploy; a chained preparation step (`terraform init && …`) is not.
    Fail open: an unreadable config (a template's placeholders included) or a null adapter → no class."""
    try:
        d = json.loads((Path(repo) / "config/quality.json").read_text(encoding="utf-8")).get("delivery")
    except (OSError, ValueError, AttributeError):
        return None, []
    adapter = d.get("adapter") if isinstance(d, dict) else None
    if not isinstance(adapter, dict):
        return None, []
    heads = []
    for key in ("apply", "destroy"):
        cmd = adapter.get(key)
        if not isinstance(cmd, str) or not cmd.strip():
            continue
        for args in list(_argvs(Path(repo), cmd, None, {}))[-1:]:
            words = []
            for w in args:
                if w.startswith("-") or "{" in w:   # a flag or a row placeholder ends the head: `fly apps destroy {app}`
                    break
                words.append(w)
            if words and words[0] != "cd" and words not in heads:
                heads.append(words)
    return d.get("execution"), heads


# launchers that run the next words as the command, with the option values they take (EVOL-081 deny)
LAUNCHERS = {"npx": 0, "pnpx": 0, "bunx": 0, "timeout": 1, "nice": 0, "nohup": 0, "xargs": 0, "eval": 0, "stdbuf": 0,
             "sudo": 0, "env": 0, "command": 0, "exec": 0, "time": 0}
VALUED = {"sudo": {"-u", "-g", "-C", "-h", "-p", "-r", "-t", "-U"}, "env": {"-u", "-C", "-S"}, "nice": {"-n"},
          "timeout": {"-s", "-k", "--signal", "--kill-after"}, "xargs": {"-I", "-n", "-P", "-L", "-d", "-a", "-E", "-s"}}
ALIASES = {"flyctl": ["fly"], "docker-compose": ["docker", "compose"]}   # one tool, one spelling
GATE_DEPLOY = {"--run", "--rollback", "--teardown"}


def _unwrap(args: list[str]) -> list[str]:
    """The command a launcher runs: `npx cdk deploy` → cdk deploy, `timeout 600 sudo -u x tf apply` → tf apply."""
    while args and os.path.basename(args[0]) in LAUNCHERS:
        name, rest = os.path.basename(args[0]), args[1:]
        while rest and (rest[0].startswith("-") or ASSIGN.match(rest[0])):
            flag = rest.pop(0)
            if flag in VALUED.get(name, ()) and rest:
                rest.pop(0)
        for _ in range(LAUNCHERS[name]):   # `timeout DURATION`
            if rest:
                rest.pop(0)
        args = rest
    return args


def _spelled(argv: list[str]) -> list[str]:
    b = os.path.basename(argv[0])
    return ALIASES.get(b, [b]) + list(argv[1:])


def _subcommand_at(args: list[str]) -> list[int]:
    """The positions that may hold the subcommand: the first word after the tool, or — while each candidate follows a
    bare global flag (`--access-token T`, `-n x`, `--context prod`) — the word after it. A word that follows no bare flag
    ends the chain, so a subcommand's own values never count (`terraform plan -out apply` is plan)."""
    out, bare = [], False
    for i, w in enumerate(args[1:], 1):
        if w.startswith("-"):
            bare = "=" not in w
            continue
        out.append(i)
        if not bare:
            break
        bare = False
    return out


def _runs_head(args: list[str], head: list[str]) -> bool:
    """argv runs the head: the same tool (aliases spelled one way — `docker-compose` is `docker compose`), the head's
    subcommand where a subcommand can stand, the head's further words in order among the rest — flags anywhere."""
    if not args:
        return False
    args, head = _spelled(args), _spelled(head)
    if args[0] != head[0]:
        return False
    if len(head) == 1:
        return True
    for i in _subcommand_at(args):
        if args[i] == head[1]:
            it = iter(w for w in args[i + 1:] if not w.startswith("-"))
            if all(any(w == h for w in it) for h in head[2:]):
                return True
    return False


def _runs_executor(args: list[str]) -> bool:
    """`gate.py delivery --run|--rollback|--teardown` — the executor run on a workstation (CI=1 would pass its guard)."""
    i = next((k for k, w in enumerate(args) if os.path.basename(w) == "gate.py"), None)
    return i is not None and "delivery" in args[i + 1:] and bool(GATE_DEPLOY & set(args[i + 1:]))


def deploy_class(repo: Path, payload: dict, env: dict | None = None) -> str | None:
    """The project's delivery.execution when the Bash command runs the adapter's own apply / destroy, else None."""
    ti = payload.get("tool_input") or {}
    if (payload.get("tool_name") or ("Bash" if "command" in ti else "")) != "Bash":
        return None
    execution, heads = _deploy_row(repo)
    if not heads:
        return None
    env = dict(os.environ if env is None else env)
    for args in _argvs(Path(os.path.realpath(repo)), str(ti.get("command") or ""), payload.get("cwd") or None, env):
        args = _unwrap(list(args))
        if _runs_executor(args) or any(_runs_head(args, h) for h in heads):
            return execution if isinstance(execution, str) else ""
    return None


def verdict(repo: Path, payload: dict, env: dict | None = None) -> tuple[int, str]:
    """(rc, text): 0 + in-project targets one per line · 4 nothing to judge · 1 + the humanised reason
    · 5 a deploy command (the adapter's apply / destroy) in a project that deploys from its pipeline (EVOL-081).
    Never 3: that is gate.py's import guard (the package missing or broken), which a hook must read as a fault."""
    t = targets(repo, payload, env)
    if t["guarded"]:
        return 1, (f"BLOCKED: this write lands on the harness or user configuration ({', '.join(t['guarded'])}) — guarded on every branch.\n"
                   "Resolution: an agent never changes its own guard rails; ask the user to make that change by hand.")
    if deploy_class(repo, payload, env) == "ci":
        return 5, "BLOCKED: This project deploys from its pipeline — run DEVOPS --deploy, which starts the pipeline and watches the run."
    if t["unresolved"]:
        return 1, (f"BLOCKED: the shell command writes to a target the guard cannot name before it runs — {t['unresolved']}.\n"
                   "Resolution: make the write with Edit or Write, or give the shell command a literal path, so the branch rule and the planning stage can judge it.")
    if t["pathless"]:
        return 0, ""
    if not t["writer"] or not t["inside"]:
        return 4, ""
    return 0, "\n".join(t["inside"])
